import{_ as e,o as d,c as r,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/settings.md","filePath":"car-wash/settings.md"}'),a={name:"car-wash/settings.md"};function s(n,t,h,c,i,l){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Every Car Wash setting is edited in <code>/nay</code>, on the <strong>Car Wash</strong> page (scope <code>nay_car_wash.config</code>). Changes are saved in the database and applied to every player at once. <code>config.lua</code> holds optional starting values: they apply until a setting is changed in <code>/nay</code>, and <strong>Reset</strong> goes back to them.</p><p>The <strong>In /nay</strong> column is the name shown in the panel. The key is the name used by <code>config.lua</code> and the <a href="/nay-lib/api">HTTP API</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enabled</td><td><code>Enabled</code></td><td>on / off</td><td>on</td><td>Turns every tunnel and pressure washer on or off.</td></tr><tr><td>On-foot interaction</td><td><code>InteractionMode</code></td><td><code>key</code> or <code>target</code></td><td><code>key</code></td><td>How players start a pressure washer: key prompt (E) or target eye. Tunnels always use E from the vehicle.</td></tr><tr><td>Payment account</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> or <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Where the price is taken from. <code>cash_then_bank</code> uses the bank when cash is short.</td></tr><tr><td>Job discounts</td><td><code>JobDiscounts</code></td><td>list, up to 32</td><td>none</td><td>Discounts for a job from a grade, on tunnels and pressure washers.</td></tr></tbody></table><p><strong>Job discounts</strong> entries:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>text, 1 to 32 characters</td><td>Job name, as in your framework.</td></tr><tr><td>Minimum grade</td><td><code>MinGrade</code></td><td>number, 0 to 100</td><td>Lowest grade that gets the discount.</td></tr><tr><td>Discount (%)</td><td><code>Percent</code></td><td>number, 1 to 100</td><td>Discount in percent. 100 makes it free.</td></tr></tbody></table><h2 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Wash programs</td><td><code>Programs</code></td><td>list, 1 to 8</td><td>Express $150, Standard $250, Premium $400</td><td>Wash programs offered in every tunnel.</td></tr><tr><td>Tunnels</td><td><code>Tunnels</code></td><td>list, up to 32</td><td>Strawberry, Little Seoul</td><td>The tunnels. Placed with the <a href="/car-wash/tunnels">tunnel editor</a>.</td></tr><tr><td>Maximum vehicle width (m)</td><td><code>MaxVehicleWidth</code></td><td>meters, 1 to 6</td><td>2.25</td><td>Wider vehicles are refused.</td></tr><tr><td>Blocked vehicle classes</td><td><code>BlockedClasses</code></td><td>list of vehicle classes</td><td>motorcycles, cycles, boats, helicopters, planes, trains</td><td>Vehicle classes refused at the entrance.</td></tr><tr><td>Refuse clean vehicles</td><td><code>RequireDirt</code></td><td>on / off</td><td>off</td><td>Refuses vehicles that are already clean.</td></tr><tr><td>Swap map car wash IPLs</td><td><code>ReplaceMapIpls</code></td><td>on / off</td><td>on</td><td>At Strawberry, swaps the default car wash for its brushless version. Turn it off when a custom map or a mapping manager handles that car wash.</td></tr></tbody></table><p><strong>Wash programs</strong> entries:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>text, 1 to 32 characters</td><td>Name shown in the wash menu.</td></tr><tr><td>Price</td><td><code>Price</code></td><td>number, 0 to 1000000</td><td>Price before discounts and the tunnel percentage.</td></tr><tr><td>Speed (%)</td><td><code>SpeedPercent</code></td><td>number, 25 to 300</td><td>Speed relative to the tunnel speed.</td></tr><tr><td>Soap</td><td><code>Soap</code></td><td>on / off</td><td>Runs the soap arch.</td></tr><tr><td>Rinse</td><td><code>Rinse</code></td><td>on / off</td><td>Runs the rinse arch.</td></tr><tr><td>Dry</td><td><code>Dry</code></td><td>on / off</td><td>Runs the dryer.</td></tr><tr><td>Wax (minutes)</td><td><code>WaxMinutes</code></td><td>number, 0 to 1440</td><td>Minutes the vehicle stays clean after the wash. 0 means no wax.</td></tr></tbody></table><p><strong>Tunnels</strong> entries are easier to edit with the <a href="/car-wash/tunnels">tunnel editor</a>, which fills these fields for you:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>text, up to 48 characters</td><td>Title of the wash menu, also used in the history and webhooks. Optional.</td></tr><tr><td>Open</td><td><code>Enabled</code></td><td>on / off</td><td>Closes one tunnel without deleting it.</td></tr><tr><td>Entrance</td><td><code>Entry</code></td><td>position and heading</td><td>Where the driver stops and presses E.</td></tr><tr><td>Line start</td><td><code>Start</code></td><td>position</td><td>Start of the line the vehicle follows.</td></tr><tr><td>Line end</td><td><code>Finish</code></td><td>position</td><td>End of the line.</td></tr><tr><td>Width (m)</td><td><code>Width</code></td><td>meters, 2 to 10</td><td>Lane width: sizes the arches, limits the vehicle width (0.5 m margin) and is used by the blocked-lane check.</td></tr><tr><td>Speed (m/s)</td><td><code>Speed</code></td><td>meters per second, 0.5 to 8</td><td>Base speed through the tunnel, multiplied by the program speed.</td></tr><tr><td>Price (%)</td><td><code>PricePercent</code></td><td>number, 0 to 1000</td><td>Percentage applied to every program price in this tunnel. 100 keeps the prices.</td></tr><tr><td>Soap arch</td><td><code>SoapJet</code></td><td>position</td><td>Soap arch.</td></tr><tr><td>Top brush</td><td><code>HorizontalRoller</code></td><td>position</td><td>Top brush.</td></tr><tr><td>Side brushes</td><td><code>VerticalRoller</code></td><td>position</td><td>Side brushes.</td></tr><tr><td>Rinse arch</td><td><code>RinseJet</code></td><td>position</td><td>Rinse arch.</td></tr><tr><td>Dryer</td><td><code>Dryer</code></td><td>position</td><td>Steam dryer. Optional.</td></tr></tbody></table><p><strong>Blocked vehicle classes</strong> entries have one field, <strong>Class</strong> (<code>Class</code>), picked from the GTA vehicle classes by name.</p><h2 id="pressure-washers" tabindex="-1">Pressure washers <a class="header-anchor" href="#pressure-washers" aria-label="Permalink to &quot;Pressure washers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Pressure washers</td><td><code>ManualEnabled</code></td><td>on / off</td><td>on</td><td>Turns the pressure washers on or off.</td></tr><tr><td>Pressure washer props</td><td><code>ManualModels</code></td><td>list, up to 16</td><td><code>prop_gas_airunit01</code></td><td>World props that become pressure washers, wherever the map has them.</td></tr><tr><td>Placed pressure washers</td><td><code>ManualStations</code></td><td>list, up to 64</td><td>none</td><td>Pressure washers you place yourself.</td></tr><tr><td>Price per dirt level</td><td><code>ManualPricePerLevel</code></td><td>number, 0 to 100000</td><td>15</td><td>Price of one dirt level, before job discounts.</td></tr><tr><td>Seconds per dirt level</td><td><code>ManualSecondsPerLevel</code></td><td>seconds, 0.2 to 10</td><td>1</td><td>Time to clean one dirt level.</td></tr></tbody></table><p><strong>Pressure washer props</strong> entries have one field, <strong>Model name</strong> (<code>Model</code>): the prop model name (letters, digits and underscores).</p><p><strong>Placed pressure washers</strong> entries:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>text, up to 48 characters</td><td>Name of the station, used in the history and webhooks. Optional.</td></tr><tr><td>Position</td><td><code>Coords</code></td><td>position and heading</td><td>Where it stands. <strong>Use my position</strong> fills it from where you stand.</td></tr></tbody></table><p>More on the <a href="/car-wash/pressure-washers">Pressure washers</a> page.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show blips</td><td><code>ShowBlips</code></td><td>on / off</td><td>on</td><td>Shows the tunnels and, while pressure washers are on, the placed stations on the map.</td></tr><tr><td>Blip sprite</td><td><code>BlipSprite</code></td><td>blip icon</td><td>100</td><td>Picked from a visual list of icons. Any number can still be typed for a custom blip.</td></tr><tr><td>Blip color</td><td><code>BlipColor</code></td><td>blip colour</td><td>63</td><td>Picked from a visual list of colours.</td></tr><tr><td>Blip scale</td><td><code>BlipScale</code></td><td>0.2 to 2</td><td>0.8</td><td>Size of the blip.</td></tr></tbody></table>',22)])])}const b=e(a,[["render",s]]);export{u as __pageData,b as default};
